-- Generated by matugen for Hush. A role-driven colorscheme on Material surfaces.
-- base16 is deliberately not used: on wallpaper-sourced themes matugen's base16 collapses to
-- near-background colours (contrast ~1.0, every token invisible) and on light themes it stays
-- tuned for dark backgrounds. Syntax colours come from the mode-aware roles instead (primary,
-- secondary, tertiary, error; tone ~80 on dark, ~40 on light), hue-spread from primary for the
-- extra token kinds, then clamped: each is lightened (dark) or darkened (light) until it clears
-- its contrast floor on the background AND the cursor line (4.5, comments and line numbers 3.0).
local dark = "{{mode}}" == "dark"
local c = {
  bg = "{{colors.surface.default.hex}}", bg1 = "{{colors.surface_container.default.hex}}",
  bg2 = "{{colors.surface_container_high.default.hex}}", bg3 = "{{colors.surface_container_highest.default.hex}}",
  fg = "{{colors.on_surface.default.hex}}", fg_dim = "{{colors.on_surface_variant.default.hex}}",
  outline = "{{colors.outline.default.hex}}", outline_v = "{{colors.outline_variant.default.hex}}",
  primary = "{{colors.primary.default.hex}}", on_primary = "{{colors.on_primary.default.hex}}",
  secondary = "{{colors.secondary.default.hex}}", tertiary = "{{colors.tertiary.default.hex}}",
  error = "{{colors.error.default.hex}}",
  sel = "{{colors.secondary_container.default.hex}}", on_sel = "{{colors.on_secondary_container.default.hex}}",
}

-- colour math (sRGB hex <-> HSL, WCAG 2 contrast)
local function rgb(h) return tonumber(h:sub(2, 3), 16) / 255, tonumber(h:sub(4, 5), 16) / 255, tonumber(h:sub(6, 7), 16) / 255 end
local function hex(r, g, b)
  local f = function(x) return math.floor(math.max(0, math.min(1, x)) * 255 + 0.5) end
  return string.format("#%02x%02x%02x", f(r), f(g), f(b))
end
local function lum(h)
  local r, g, b = rgb(h)
  local l = function(x) return x <= 0.03928 and x / 12.92 or ((x + 0.055) / 1.055) ^ 2.4 end
  return 0.2126 * l(r) + 0.7152 * l(g) + 0.0722 * l(b)
end
local function contrast(a, b)
  local x, y = lum(a), lum(b)
  if x < y then x, y = y, x end
  return (x + 0.05) / (y + 0.05)
end
local function to_hsl(h)
  local r, g, b = rgb(h)
  local mx, mn = math.max(r, g, b), math.min(r, g, b)
  local l, d = (mx + mn) / 2, mx - mn
  if d == 0 then return 0, 0, l end
  local s = l > 0.5 and d / (2 - mx - mn) or d / (mx + mn)
  local hh
  if mx == r then hh = (g - b) / d % 6 elseif mx == g then hh = (b - r) / d + 2 else hh = (r - g) / d + 4 end
  return hh * 60, s, l
end
local function from_hsl(hh, s, l)
  local q = l < 0.5 and l * (1 + s) or l + s - l * s
  local p = 2 * l - q
  local t = function(x)
    x = x % 1
    if x < 1 / 6 then return p + (q - p) * 6 * x end
    if x < 1 / 2 then return q end
    if x < 2 / 3 then return p + (q - p) * (2 / 3 - x) * 6 end
    return p
  end
  local k = hh / 360
  return hex(t(k + 1 / 3), t(k), t(k - 1 / 3))
end
-- same lightness as primary, hue rotated, chroma floored so the token reads as a colour
local function spin(h, deg)
  local hh, s, l = to_hsl(h)
  return from_hsl((hh + deg) % 360, math.max(s, 0.45), l)
end
-- mode-aware clamp: move lightness away from the background until every bg clears `min`
local function ensure(h, min, bgs)
  bgs = bgs or { c.bg, c.bg1 }
  local hh, s, l = to_hsl(h)
  local out = h
  for _ = 1, 100 do
    local ok = true
    for _, b in ipairs(bgs) do if contrast(out, b) < min then ok = false break end end
    if ok then return out end
    l = dark and math.min(1, l + 0.01) or math.max(0, l - 0.01)
    out = from_hsl(hh, s, l)
  end
  return out
end

-- syntax palette: six hues 60 degrees apart around primary, roles first
local p = {
  keyword = ensure(c.primary, 4.5),
  func = ensure(c.tertiary, 4.5),
  string = ensure(spin(c.primary, 120), 4.5),
  const = ensure(spin(c.primary, 180), 4.5),
  type = ensure(spin(c.primary, 300), 4.5),
  special = ensure(spin(c.primary, 240), 4.5),
  error = ensure(c.error, 4.5),
  warn = ensure(spin(c.error, 40), 4.5),
  info = ensure(c.secondary, 4.5),
  comment = ensure(c.outline, 3.0),
  linenr = ensure(c.outline, 3.0),
  fg_dim = ensure(c.fg_dim, 4.5, { c.bg, c.bg1, c.bg2 }),
}
_G.hush_palette = { c = c, p = p } -- inspected by the Hush contrast gate

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then vim.cmd("syntax reset") end
vim.o.termguicolors = true
vim.o.background = dark and "dark" or "light"
vim.g.colors_name = "hush"
local hi = function(g, o) vim.api.nvim_set_hl(0, g, o) end
