-- terminal buffers (:terminal, toggleterm) get the same mode-aware ANSI hues as kitty
vim.g.terminal_color_0 = c.bg2
vim.g.terminal_color_8 = p.comment
vim.g.terminal_color_7 = p.fg_dim
vim.g.terminal_color_15 = c.fg
for i, deg in ipairs({ 5, 125, 45, 215, 300, 185 }) do
  local hh0 = select(1, to_hsl(c.primary))
  local col = ensure(spin(c.primary, (deg - hh0) % 360), 4.5)
  vim.g["terminal_color_" .. i] = col
  vim.g["terminal_color_" .. (i + 8)] = col
end
